package com.wanyuecity.energy.usage.service;
import com.wanyuecity.energy.system.migration.MigrationMaintenance;import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import org.springframework.scheduling.annotation.Async;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;
@Slf4j(topic="platform-sync") @Component @RequiredArgsConstructor public class BalanceWarningScheduler {private final BalanceWarningService service;private final MigrationMaintenance migrationMaintenance;@Async @Scheduled(cron="0 10 9 * * *",zone="Asia/Shanghai")public void daily(){if(migrationMaintenance.isActive()){log.info("balance warning skipped during migration");return;}try{service.syncAndAnalyze("SCHEDULED_0910");}catch(Exception ex){log.error("scheduled balance warning failed: {}",ex.getMessage());}}}
